-- Local-only support schema; live identity functions and triggers snapshot at main 74747b2.
-- No user data, network extensions, queues, or outbound notification triggers.
-- Local-only PostgreSQL/PGlite verification fixture. No network, queue or notifier.
-- Relevant function bodies/trigger declarations come from the readonly live snapshot.
-- Minimal support tables are not a replacement for canonical schema/RLS validation.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema private;
grant usage on schema public, auth to anon, authenticated, service_role;
grant usage on schema private to authenticated, service_role;
create function auth.uid() returns uuid language sql stable as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
create function auth.role() returns text language sql stable as $$
  select coalesce(nullif(current_setting('request.jwt.claim.role', true), ''), current_user::text)
$$;
create table auth.users (
  id uuid primary key, email text, email_confirmed_at timestamptz, phone_confirmed_at timestamptz,
  last_sign_in_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz default now()
);
create table public.staff_members (
  user_id uuid primary key references auth.users(id), role text not null, active boolean not null default true
);

create table public.account_profiles (
  id uuid not null,
  username text not null,
  full_name text not null,
  avatar_url text,
  email_updates boolean default false not null,
  whatsapp_e164 text,
  whatsapp_updates boolean default false not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  whatsapp_verified_at timestamp with time zone,
  birth_date date,
  primary key (id),
  unique (username)
);

create table public.social_profiles (
  id uuid not null,
  username text not null,
  display_name text not null,
  bio text default ''::text not null,
  avatar_key text,
  header_key text,
  website_url text,
  location text,
  is_discoverable boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  followers_count integer default 0 not null,
  following_count integer default 0 not null,
  allow_external_indexing boolean default true not null,
  dm_access text default 'everyone'::text not null,
  is_verified boolean default false not null,
  verification_badge_type text default 'standard'::text not null,
  username_locked_at timestamp with time zone,
  professional_category_slug text,
  primary key (id),
  unique (username)
);

create table private.moderation_staff (
  user_id uuid primary key references public.social_profiles(id), staff_role text not null,
  active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now()
);
revoke all on private.moderation_staff from public, anon, authenticated;
create table private.reserved_username_assignments (user_id uuid not null, username text not null, primary key(user_id, username));
create table private.signup_policy (singleton boolean primary key, activated_at timestamptz, phone_required boolean);
insert into private.signup_policy values (true, '2026-10-02', false);
create table private.signup_acceptances (user_id uuid primary key);
create table public.social_identity_change_events (
  id bigint generated by default as identity primary key,
  user_id uuid not null references public.social_profiles(id), change_type text not null,
  old_value text not null, new_value text not null, source text not null,
  request_id uuid, changed_at timestamptz not null default now(), unique(user_id,request_id)
);

CREATE OR REPLACE FUNCTION private.sync_social_profile_from_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
begin
  if caller_id is not null and caller_id <> new.id then
    raise exception 'account profile identity mismatch';
  end if;

  insert into public.social_profiles (id, username, display_name)
  values (new.id, new.username, new.full_name)
  on conflict (id) do update
    set username = excluded.username;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.prevent_locked_social_username_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.username is distinct from old.username
     and (old.username_locked_at is not null or new.is_verified) then
    raise exception 'USERNAME_LOCKED_VERIFIED' using errcode = 'P0001';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.prevent_locked_account_username_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.username is distinct from old.username
     and exists (
       select 1
       from public.social_profiles profile
       where profile.id = old.id
         and (profile.username_locked_at is not null or profile.is_verified)
     ) then
    raise exception 'USERNAME_LOCKED_VERIFIED' using errcode = 'P0001';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_reserved_username_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if lower(new.username) = any (array[
    'admin','administrator','root','support','security','sautilink',
    'cloudengine','official','api','help','about','settings','login',
    'signup','account','privacy','terms','contact','waitlist'
  ]::text[]) then
    if not exists (
      select 1
      from private.reserved_username_assignments assignment
      where assignment.user_id = new.id
        and assignment.username = lower(new.username)
    ) then
      raise exception 'RESERVED_USERNAME' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.require_new_signup_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  created_at timestamptz;
  account_email text;
  email_confirmed_at timestamptz;
  phone_confirmed_at timestamptz;
  activated_at timestamptz;
  require_phone boolean;
begin
  select u.created_at, u.email, u.email_confirmed_at, u.phone_confirmed_at
    into created_at, account_email, email_confirmed_at, phone_confirmed_at
    from auth.users u where u.id = new.id;
  select p.activated_at, p.phone_required into activated_at, require_phone
    from private.signup_policy p where p.singleton = true;

  -- Email is the mandatory identity for new signup, including trusted inserts.
  -- Keep old-account exemptions and the existing privileged agreement/phone split.
  if created_at >= activated_at and
      (nullif(btrim(account_email), '') is null or email_confirmed_at is null) then
    raise exception using errcode = '42501', message = 'VERIFIED_EMAIL_REQUIRED';
  end if;

  if auth.uid() is distinct from new.id then
    return new;
  end if;

  if created_at >= activated_at then
    if not exists (
      select 1 from private.signup_acceptances a where a.user_id = new.id
    ) then
      raise exception using errcode = '42501', message = 'SIGNUP_TERMS_REQUIRED';
    end if;
    if require_phone and phone_confirmed_at is null then
      raise exception using errcode = '42501', message = 'VERIFIED_PHONE_REQUIRED';
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.apply_permanent_username_lock_on_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.is_verified and new.username_locked_at is null then
      new.username_locked_at := now();
    end if;
    return new;
  end if;

  if old.username_locked_at is not null then
    new.username_locked_at := old.username_locked_at;
  elsif new.is_verified and new.username_locked_at is null then
    new.username_locked_at := now();
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.change_social_identity_privileged(p_change_type text, p_value text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_uid uuid := auth.uid();
  profile_row public.social_profiles%rowtype;
  normalized_type text := lower(btrim(coalesce(p_change_type, '')));
  normalized_value text := btrim(coalesce(p_value, ''));
  recent_count integer := 0;
  month_start timestamptz := date_trunc('month', now());
  next_month_start timestamptz := date_trunc('month', now()) + interval '1 month';
begin
  if current_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if p_request_id is null then
    raise exception 'REQUEST_ID_REQUIRED' using errcode = '22023';
  end if;

  select *
  into profile_row
  from public.social_profiles
  where id = current_uid
  for update;

  if not found then
    raise exception 'PROFILE_UNAVAILABLE' using errcode = 'P0002';
  end if;

  if normalized_type = 'display_name' then
    if char_length(normalized_value) < 1 or char_length(normalized_value) > 80 then
      raise exception 'DISPLAY_NAME_INVALID' using errcode = '22023';
    end if;

    if normalized_value = profile_row.display_name then
      return jsonb_build_object(
        'status', 'unchanged',
        'change_type', 'display_name',
        'display_name', profile_row.display_name,
        'username', profile_row.username,
        'is_verified', profile_row.is_verified
      );
    end if;

    if profile_row.is_verified then
      select count(*)::integer
      into recent_count
      from public.social_identity_change_events
      where user_id = current_uid
        and change_type = 'display_name'
        and changed_at >= month_start
        and changed_at < next_month_start;

      if recent_count >= 2 then
        raise exception 'VERIFIED_DISPLAY_NAME_MONTHLY_LIMIT' using errcode = 'P0001';
      end if;

      update public.social_profiles
      set display_name = normalized_value
      where id = current_uid;

      update public.account_profiles
      set full_name = normalized_value
      where id = current_uid;

      insert into public.social_identity_change_events (
        user_id, change_type, old_value, new_value, source, request_id
      )
      values (
        current_uid, 'display_name', profile_row.display_name, normalized_value, 'member', p_request_id
      );

      return jsonb_build_object(
        'status', 'changed',
        'change_type', 'display_name',
        'display_name', normalized_value,
        'username', profile_row.username,
        'is_verified', true,
        'remaining_in_month', 1 - recent_count,
        'next_month_starts_at', next_month_start
      );
    end if;

    select count(*)::integer
    into recent_count
    from public.social_identity_change_events
    where user_id = current_uid
      and change_type = 'display_name'
      and changed_at > now() - interval '14 days';

    if recent_count >= 2 then
      raise exception 'DISPLAY_NAME_CHANGE_LIMIT' using errcode = 'P0001';
    end if;

    update public.social_profiles
    set display_name = normalized_value
    where id = current_uid;

    update public.account_profiles
    set full_name = normalized_value
    where id = current_uid;

    insert into public.social_identity_change_events (
      user_id, change_type, old_value, new_value, source, request_id
    )
    values (
      current_uid, 'display_name', profile_row.display_name, normalized_value, 'member', p_request_id
    );

    return jsonb_build_object(
      'status', 'changed',
      'change_type', 'display_name',
      'display_name', normalized_value,
      'username', profile_row.username,
      'is_verified', false,
      'remaining_in_14_days', 1 - recent_count
    );
  end if;

  if normalized_type = 'username' then
    normalized_value := lower(normalized_value);

    if normalized_value !~ '^[a-z0-9][a-z0-9._]{2,29}$' then
      raise exception 'USERNAME_INVALID' using errcode = '22023';
    end if;

    if normalized_value = any (array[
      'admin','administrator','root','support','security','sautilink','cloudengine',
      'official','api','help','about','settings','login','signup','account','privacy',
      'terms','contact','waitlist'
    ]) then
      raise exception 'USERNAME_RESERVED' using errcode = '22023';
    end if;

    if normalized_value = profile_row.username then
      return jsonb_build_object(
        'status', 'unchanged',
        'change_type', 'username',
        'display_name', profile_row.display_name,
        'username', profile_row.username,
        'is_verified', profile_row.is_verified
      );
    end if;

    if profile_row.username_locked_at is not null or profile_row.is_verified then
      raise exception 'USERNAME_LOCKED_VERIFIED' using errcode = 'P0001';
    end if;

    select count(*)::integer
    into recent_count
    from public.social_identity_change_events
    where user_id = current_uid
      and change_type = 'username'
      and changed_at > now() - interval '30 days';

    if recent_count >= 1 then
      raise exception 'USERNAME_CHANGE_LIMIT' using errcode = 'P0001';
    end if;

    begin
      update public.account_profiles
      set username = normalized_value
      where id = current_uid;
    exception
      when unique_violation then
        raise exception 'USERNAME_TAKEN' using errcode = '23505';
      when check_violation then
        raise exception 'USERNAME_INVALID' using errcode = '22023';
    end;

    insert into public.social_identity_change_events (
      user_id, change_type, old_value, new_value, source, request_id
    )
    values (
      current_uid, 'username', profile_row.username, normalized_value, 'member', p_request_id
    );

    return jsonb_build_object(
      'status', 'changed',
      'change_type', 'username',
      'display_name', profile_row.display_name,
      'username', normalized_value,
      'is_verified', profile_row.is_verified,
      'next_username_change_at', now() + interval '30 days'
    );
  end if;

  raise exception 'IDENTITY_CHANGE_TYPE_INVALID' using errcode = '22023';
end;
$function$;

CREATE OR REPLACE FUNCTION public.change_social_identity(p_change_type text, p_value text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.change_social_identity_privileged(
    p_change_type,
    p_value,
    p_request_id
  );
$function$;

alter table public.account_profiles add foreign key (id) references auth.users(id);
alter table public.social_profiles add foreign key (id) references public.account_profiles(id);
revoke all on all tables in schema public,private from public,anon,authenticated;
grant select on public.social_profiles,public.account_profiles to authenticated;
revoke all on all functions in schema public,private from public,anon,authenticated;
grant execute on function private.change_social_identity_privileged(text,text,uuid),public.change_social_identity(text,text,uuid) to authenticated;
CREATE TRIGGER account_profiles_enforce_reserved_username BEFORE INSERT OR UPDATE OF id, username ON public.account_profiles FOR EACH ROW EXECUTE FUNCTION private.enforce_reserved_username_assignment();
CREATE TRIGGER account_profiles_prevent_locked_username_change BEFORE UPDATE OF username ON public.account_profiles FOR EACH ROW EXECUTE FUNCTION private.prevent_locked_account_username_change();
CREATE TRIGGER account_profiles_require_new_signup_ready BEFORE INSERT ON public.account_profiles FOR EACH ROW EXECUTE FUNCTION private.require_new_signup_ready();
CREATE TRIGGER sync_social_profile_from_account AFTER INSERT OR UPDATE OF username ON public.account_profiles FOR EACH ROW EXECUTE FUNCTION private.sync_social_profile_from_account();
CREATE TRIGGER social_profiles_enforce_reserved_username BEFORE INSERT OR UPDATE OF id, username ON public.social_profiles FOR EACH ROW EXECUTE FUNCTION private.enforce_reserved_username_assignment();
CREATE TRIGGER social_profiles_lock_username_on_verification_insert BEFORE INSERT ON public.social_profiles FOR EACH ROW EXECUTE FUNCTION private.apply_permanent_username_lock_on_verification();
CREATE TRIGGER social_profiles_lock_username_on_verification_update BEFORE UPDATE OF is_verified, username_locked_at ON public.social_profiles FOR EACH ROW EXECUTE FUNCTION private.apply_permanent_username_lock_on_verification();
CREATE TRIGGER social_profiles_prevent_locked_username_change BEFORE UPDATE OF username ON public.social_profiles FOR EACH ROW EXECUTE FUNCTION private.prevent_locked_social_username_change();

alter table public.social_profiles enable row level security;
create policy fixture_profiles_read on public.social_profiles for select to authenticated using (true);
alter table public.account_profiles enable row level security;
create policy fixture_account_owner_read on public.account_profiles for select to authenticated using (auth.uid()=id);
